00083 static int32_t create_context(CodecContext *cp, const char *json_configuration, CodecError *error) {
00084     if (error)
00085         *error = 0;
00086 
00087     Context *context = new Context();
00088     context->configuration_ = json_configuration;
00089     context->state_ = StatePushing;
00090     *cp = (void *)context;
00091 
00092     return 1;
00093 }
00094 
00095 // Push encoded data into decoder
00096 //
00097 // To avoid messing with JM any more than necessary, this cheats a bit and saves the entire input bitstream
00098 // until EOS, then starts the JM decoder with the whole stream.
00099 //
00100 static int32_t push_packet(CodecContext c, const uint8_t *data, size_t length, CodecMetadata metadata, int8_t eos,
00101                            CodecError *error) {
00102     Context *context = (Context *)c;
00103     if (error)
00104         *error = 0;
00105 
00106     switch (context->state_) {
00107     case StatePushing:
00108         if (!eos) {
00109             CHECK(data);
00110             CHECK(length >= 3);
00111             // Fixup NALU start code - if first is 3 bytes, make it 4
00112             if (data[0] == '\0' && data[1] == '\0' && data[2] == '\1') {
00113                 char const zero = '\0';
00114                 context->base_bitstream_.push_back(0);
00115             }
00116 
00117             // Accumulate AUs into a temporary buffer
00118             context->base_bitstream_.insert(context->base_bitstream_.end(), data, data + length);
00119         } else {
00121             context->state_ = StateDecoding;
00122         }
00123         return 0;
00124 
00125     default:
00126         ERR("Unexpected decoder state");
00127     }
00128 
00129     return 0;
00130 }
00131 
00132 static bool extract_image(DecodedPicList *pic, CodecImage *codec_image) {
00133 
00134     // Is there a picture?
00135     if (!pic || !pic->pY || !pic->pU || !pic->pV) {
00136         return false;
00137     }
00138 
00139     if (!pic->bValid) {
00140         INFO("Picture not marked valid?");
00141         return false;
00142     }
00143 
00144     CHECK(codec_image);
00145     codec_image->bpp = ((pic->iBitDepth + 7) >> 3);
00146     codec_image->width_y = pic->iWidth;
00147     codec_image->height_y = pic->iHeight;
00148     codec_image->stride_y = pic->iYBufStride;
00149 
00150     codec_image->width_uv = (pic->iYUVFormat != YUV444) ? (pic->iWidth / 2) : pic->iWidth;
00151     codec_image->height_uv = (pic->iYUVFormat == YUV420) ? (pic->iHeight / 2) : pic->iHeight;
00152     codec_image->stride_uv = pic->iUVBufStride;
00153 
00154     codec_image->data_y = pic->pY;
00155     codec_image->data_u = pic->pU;
00156     codec_image->data_v = pic->pV;
00157 
00158     return true;
00159 }
00160 
00161 static int32_t pull_image(CodecContext c, CodecImage *image, CodecMetadata *metadata, int8_t *eos, CodecError *error) {
00162     Context *context = (Context *)c;
00163     if (error)
00164         *error = 0;
00165 
00166     switch (context->state_) {
00167     case StatePushing:
00168         // Still accumulating input stream
00169         *eos = 0;
00170         return 0;
00171 
00172     case StateDecoding:
00173         context->decoder_thread_ = std::thread([context] {
00174             context->flush();
00175             context->decoded_images_.push(nullptr);
00176         });
00177 
00178         context->state_ = StateFlushing;
00179         /* Fall through */
00180 
00181     case StateFlushing:
00182         context->decoded_images_.pop(context->decoded_image_);
00183         if (context->decoded_image_) {
00184             *image = context->decoded_image_->image_;
00185             *eos = 0;
00186             return 1;
00187         } else {
00188             if (context->decoder_thread_.joinable())
00189                 context->decoder_thread_.join();
00190             *eos = 1;
00191             return 0;
00192         }
00193     default:
00194         ERR("Unexpected decoder state");
00195     }
00196 
00197     return 0;
00198 }
