00200 //
00201 //
00202 void Context::flush() {
00203 
00204     // Poke bitstream into our JM hooks
00205     inject_annex_b_bitstream(base_bitstream_.data(), (unsigned)base_bitstream_.size());
00206 
00207     InputParameters input_parameters;
00208     memset(&input_parameters, 0, sizeof(input_parameters));
00209     strcpy(input_parameters.infile, "");
00210     strcpy(input_parameters.outfile, "");
00211     strcpy(input_parameters.reffile, "");
00212 
00213     const char *const decoder_args[] = {"ldecod"};
00214     ParseCommand(&input_parameters, ARRAY_SIZE(decoder_args), (char **)decoder_args);
00215 
00216     // Open decoder
00217     if (OpenDecoder(&input_parameters) != DEC_OPEN_NOERR) {
00218         ERR("Cannot open base decoder");
00219     }
00220 
00221     p_Dec->p_Vid->p_out = -2;
00222 
00223     // Run decoder
00224     //
00225     DecodedPicList *pDecPicList = 0;
00226     int frame_count = 0;
00227 
00228     int r = 0;
00229     do {
00230         r = DecodeOneFrame(&pDecPicList);
00231 
00232         if (r == DEC_EOS || r == DEC_SUCCEED) {
00233             decode_enhanced_frames(pDecPicList, false);
00234             frame_count++;
00235         } else {
00236             ERR("Error in decoding process: 0x%x", r);
00237         }
00238     } while ((r == DEC_SUCCEED) && ((p_Dec->p_Inp->iDecFrmNum == 0) || (frame_count < p_Dec->p_Inp->iDecFrmNum)));
00239 
00240     FinitDecoder(&pDecPicList);
00241 
00242     // Write last frame
00243     decode_enhanced_frames(pDecPicList, true);
00244 
00245     CloseDecoder();
00246 }
00247 
00248 //
00249 //
00250 void Context::decode_enhanced_frames(DecodedPicList *pic, bool all_frames) {
00251     // Check picture and plane pointers - valid flag seems to be wrong sometimes!?
00252     if (!pic || !pic->pY || !pic->pU || !pic->pV) {
00253         return;
00254     }
00255 
00256     if (!pic->bValid) {
00257         INFO("Picture not marked valid?");
00258     }
00259 
00260     do {
00261         auto output_image = std::shared_ptr<DecodedImage>(new DecodedImage());
00262 
00263         output_image->image_.bpp = ((pic->iBitDepth + 7) >> 3);
00264         output_image->image_.width_y = pic->iWidth;
00265         output_image->image_.height_y = pic->iHeight;
00266         output_image->image_.stride_y = pic->iYBufStride;
00267 
00268         output_image->image_.width_uv = (pic->iYUVFormat != YUV444) ? (pic->iWidth / 2) : pic->iWidth;
00269         output_image->image_.height_uv = (pic->iYUVFormat == YUV420) ? (pic->iHeight / 2) : pic->iHeight;
00270         output_image->image_.stride_uv = pic->iUVBufStride;
00271 
00272         const size_t plane_size_y = output_image->image_.height_y * output_image->image_.stride_y;
00273         const size_t plane_size_uv = output_image->image_.height_uv * output_image->image_.stride_uv;
00274 
00275         output_image->buffer_.reserve(plane_size_y + 2 * plane_size_uv);
00276 
00277         memcpy(output_image->buffer_.data(), pic->pY, plane_size_y);
00278         memcpy(output_image->buffer_.data() + plane_size_y, pic->pU, plane_size_uv);
00279         memcpy(output_image->buffer_.data() + plane_size_y + plane_size_uv, pic->pV, plane_size_uv);
00280 
00281         output_image->image_.data_y = output_image->buffer_.data();
00282         output_image->image_.data_u = output_image->image_.data_y + plane_size_y;
00283         output_image->image_.data_v = output_image->image_.data_u + plane_size_uv;
00284 
00285         decoded_images_.push(output_image);
00286         // Mark as used and move to next
00287         pic->bValid = 0;
00288         pic = pic->pNext;
00289     } while (pic != NULL && pic->bValid && all_frames);
00290 }
